urlset:
{% set SITEURL = SITEURL_ORG %}

  {% for main_page in pages %}
    {% set all_variants = [main_page] + main_page.translations %}

    {% for page in all_variants %}
      {% set canonical_url = (SITEURL ~ '/' ~ page.url) if page.url else (SITEURL ~ '/') %}


        {{ canonical_url }}

        {% set last_date = page.modified or page.date or None %}
        {% if last_date %}
          {{ last_date.strftime('%Y-%m-%d') }}
        {% endif %}

          monthly
        {% if page and page.sitemap_priority is defined and page.sitemap_priority %}
          {{ page.sitemap_priority }}
        {% else %}
          0.7
        {% endif %}

        {% for link_page in all_variants %}
          {% set link_url = (SITEURL ~ '/' ~ link_page.url) if link_page.url else (SITEURL ~ '/') %}

        {% endfor %}


    {% endfor %}
  {% endfor %}
